use super::*;
use crate::pet_runtime::{admission_tests::{Fixture,evidence},authority_tests::{root,queued},generated_effect_tests as generated,lease_controller::{Controller,Validity},store::Store};
use crate::{chat::Chat,spotify::goal::tests::Bus};
use std::{collections::BTreeMap,path::{Path,PathBuf},process::{Command,Child,Stdio},sync::Arc,time::{Duration,Instant},thread};
use serde_json::json;
fn observed(authority:&Authority,goal:&super::super::model::Record)->Observation{let row=&goal.admissions[0];authority.owner_observation(&row.spec,row.proof.as_ref().unwrap()).unwrap()}
fn snapshot(path:&Path)->BTreeMap<PathBuf,String>{
    let mut out=BTreeMap::new();for p in std::fs::read_dir(path).unwrap(){let p=p.unwrap().path();if p.is_dir(){out.extend(snapshot(&p));}else{out.insert(p.clone(),model::hash(&std::fs::read(p).unwrap()));}}out
}
#[test]fn original_native_process_identity_is_signed_and_worker_guard_retains_the_exclusive_owner_lock(){
    let(f,a,goal,pending,owner,_main)=generated::setup(true);let identity=owner.fixture_owner_record();assert_eq!(identity.process.pid,std::process::id());assert!(identity.valid_for(owner.lease()));let before=snapshot(&f.path);let observation=observed(&a,&goal);assert_eq!(observation.state,State::OriginalProcessLive);assert!(!observation.execution_available&&!observation.recovery_available);let public=serde_json::to_value(observation).unwrap();assert!(public.get("keyId").is_none()&&public.get("ownerLock").is_none()&&public.get("bootId").is_none());assert_eq!(snapshot(&f.path),before);
    let worker=owner.readiness_worker(crate::assistant_memory::now()).unwrap();drop(owner);drop(pending);let(path,_)=a.owner_context().unwrap();let directory=protocol_directory(&path,PROTOCOL,false).unwrap().unwrap();let probe=directory.open_file(&format!("{}.lock",identity.lease_id),libc::O_RDWR).unwrap().unwrap();assert_ne!(unsafe{libc::flock(probe.as_raw_fd(),libc::LOCK_EX|libc::LOCK_NB)},0);assert_eq!(std::io::Error::last_os_error().kind(),std::io::ErrorKind::WouldBlock);drop(probe);assert_eq!(observed(&a,&goal).reason,None);drop(worker);
    let observation=observed(&a,&goal);assert_eq!(observation.state,State::OriginalProcessLive);assert_eq!(observation.reason,Some(Reason::ControllerLockNotHeld));assert!(!observation.recovery_available);
    let row=&goal.admissions[0];assert!(a.retained_absence(&row.spec,row.proof.as_ref().unwrap()).is_err());
}
#[test]fn reused_process_boot_namespace_profile_and_lock_identities_never_become_owner_absence(){
    let(f,a,goal,_pending,owner,_main)=generated::setup(true);let before=snapshot(&f.path);let original=owner.fixture_owner_record();
    for field in 0..7{let mut changed=original.clone();match field{0=>changed.process.start_ticks+=1,1=>changed.process.boot_id="00000000-0000-0000-0000-000000000000".into(),2=>changed.process.pid_namespace.inode+=1,3=>changed.profile.directory.inode+=1,4=>changed.owner_lock.inode+=1,5=>changed.owner_directory.inode+=1,_=>changed.process.uid=changed.process.uid.wrapping_add(1)};let result=observe(&a,&changed);assert_eq!(result.state,State::IdentityMismatch,"field {field}");assert!(!result.execution_available&&!result.recovery_available);}
    assert_eq!(snapshot(&f.path),before);assert!(owner.current(crate::assistant_memory::now()));assert_eq!(observed(&a,&goal).state,State::OriginalProcessLive);
}
#[test]fn unsigned_owner_changes_are_refused_and_authentic_legacy_records_stay_unknown_without_writes(){
    let(f,a,goal,_pending,_owner,_main)=generated::setup(true);let row=&goal.admissions[0];a.fixture_legacy_ownerless(&row.spec,row.proof.as_ref().unwrap()).unwrap();let before=snapshot(&f.path);let legacy=observed(&a,&goal);assert_eq!(legacy.state,State::LegacyUnknown);assert!(!legacy.recovery_available);assert_eq!(snapshot(&f.path),before);
    let file=root(&f).join(format!("{}.json",row.spec.decision_id));let mut value:serde_json::Value=serde_json::from_slice(&std::fs::read(&file).unwrap()).unwrap();value["body"]["schemaVersion"]=json!(6);value["body"]["runtimeOwner"]=json!({"schemaVersion":1,"process":{"pid":0}});std::fs::write(&file,serde_json::to_vec(&value).unwrap()).unwrap();assert!(a.owner_observation(&row.spec,row.proof.as_ref().unwrap()).is_err());
}
struct ChildGuard(Child);
impl Drop for ChildGuard{fn drop(&mut self){let _=self.0.kill();let _=self.0.wait();}}
#[test]#[ignore]fn native_owner_child(){
    let Ok(profile)=std::env::var("COUCOU_OWNER_PROFILE_NATIVE")else{return;};let bus=std::env::var("COUCOU_OWNER_BUS_NATIVE").unwrap();let ready=std::env::var("COUCOU_OWNER_READY_NATIVE").unwrap();
    let connection=dbus::blocking::Connection::new_address(&bus).unwrap();assert_eq!(connection.request_name("com.coucou.OwnerFixture.SingleInstance",false,false,true).unwrap(),dbus::blocking::stdintf::org_freedesktop_dbus::RequestNameReply::PrimaryOwner);
    let provider=std::env::var("COUCOU_OWNER_PROVIDER_NATIVE").unwrap_or_else(|_|"ollama".into());let phase=std::env::var("COUCOU_OWNER_RECOVERY_PHASE").unwrap_or_default();
    let profile=PathBuf::from(profile);let claim=crate::pet_data::fixture_native_claim(&bus,"com.coucou.OwnerFixture",&profile).unwrap();claim.current().unwrap();let f=Fixture{path:profile};let a=Authority::ensure(&root(&f)).unwrap();let goal=queued(&f,&f.goal(&provider),&a);let main=Chat::persistent(f.path.join("main-live.json"));let controller=Controller::new().unwrap();let pending=controller.prepare(&goal,&root(&f),&f.path.join("contexts"),&main,&evidence(&goal,100_006),"child-claim".into(),100_006,Arc::new(|_,_,_|Validity::Current)).unwrap();
    let mut store=f.store();if phase=="unclaimed"{store.fault=crate::pet_runtime::store::Fault::BeforePublish;}
    let owned=match pending.claim(&store,&a,&evidence(&goal,100_007),100_007){Ok((_,owner))=>owner,Err(_)if phase=="unclaimed"=>None,Err(e)=>panic!("private native child claim: {e:?}")};
    let _worker=if matches!(phase.as_str(),"started"|"settled"){
        let owner=owned.as_ref().unwrap();let call=crate::pet_runtime::effect_budget::Attempt{id:crate::pet_runtime::store::nonce().unwrap(),request_id:"original-model".into(),input_hash:"a".repeat(64),kind:crate::pet_runtime::effect_budget::Kind::Model,output_reserved:512,phase:crate::pet_runtime::effect_budget::Phase::Reserved,accepted_output:None,reserved_at:100_008,started_at:None,finished_at:None};let row=&goal.admissions[0];let proof=row.proof.as_ref().unwrap();a.reserve_attempt(&row.spec,proof,owner.lease(),&call,100_008).unwrap();a.start_attempt(&row.spec,proof,owner.lease(),&call,100_009).unwrap();if phase=="settled"{a.finish_attempt(&row.spec,proof,owner.lease(),&call,Some(64),100_010).unwrap();}Some(owner.worker(100_011).unwrap())
    }else{None};
    claim.current().unwrap();let ready=PathBuf::from(ready);let pending=ready.with_extension("pending");std::fs::write(&pending,serde_json::to_vec(&json!({"goalId":goal.id,"petId":goal.spec.owner.pet_id})).unwrap()).unwrap();std::fs::rename(pending,ready).unwrap();
    let until=Instant::now()+Duration::from_secs(20);while Instant::now()<until{claim.current().unwrap();thread::sleep(Duration::from_millis(20));}
}
#[test]fn actual_process_death_and_profile_reacquisition_report_absence_without_recreating_the_old_controller(){
    let parent=Fixture::new();let profile=parent.path.join("coucou");let ready=parent.path.join("ready.json");let bus=Bus::new();let mut child=ChildGuard(Command::new(std::env::current_exe().unwrap()).args(["--exact","pet_runtime::native_owner::tests::native_owner_child","--ignored","--nocapture"]).env("COUCOU_OWNER_PROFILE_NATIVE",&profile).env("COUCOU_OWNER_BUS_NATIVE",&bus.address).env("COUCOU_OWNER_READY_NATIVE",&ready).stdout(Stdio::null()).stderr(Stdio::null()).spawn().unwrap());
    let until=Instant::now()+Duration::from_secs(5);while !ready.exists()&&Instant::now()<until{assert!(child.0.try_wait().unwrap().is_none(),"native owner child exited before readiness");thread::sleep(Duration::from_millis(10));}assert!(ready.exists());let info:serde_json::Value=serde_json::from_slice(&std::fs::read(&ready).unwrap()).unwrap();let fixture=Fixture{path:profile.clone()};let a=Authority::existing(&root(&fixture)).unwrap();let store=Store::existing_verified(&profile.join("goals"),&root(&fixture)).unwrap().unwrap();let goal=store.read(info["goalId"].as_str().unwrap(),"ai_ollama").unwrap();let before=snapshot(&profile);assert_eq!(observed(&a,&goal).state,State::OriginalProcessLive);assert!(crate::pet_data::fixture_native_claim(&bus.address,"com.coucou.OwnerFixture",&profile).is_err());
    child.0.kill().unwrap();child.0.wait().unwrap();let connection=dbus::blocking::Connection::new_address(&bus.address).unwrap();assert_eq!(connection.request_name("com.coucou.OwnerFixture.SingleInstance",false,false,true).unwrap(),dbus::blocking::stdintf::org_freedesktop_dbus::RequestNameReply::PrimaryOwner);let claim=crate::pet_data::fixture_native_claim(&bus.address,"com.coucou.OwnerFixture",&profile).unwrap();claim.current().unwrap();let after=observed(&a,&goal);assert_eq!(after.state,State::OwnerAbsent);assert!(!after.execution_available&&!after.recovery_available);assert_eq!(snapshot(&profile),before);
    let row=&goal.admissions[0];let proof=row.proof.as_ref().unwrap();let absent=a.retained_absence(&row.spec,proof).unwrap();absent.current(&a).unwrap();assert_eq!(a.retained_absence(&row.spec,proof).err(),Some(crate::pet_runtime::authority::Failure::Busy));assert_eq!(snapshot(&profile),before);
    let held=store.reconciliation(&root(&fixture),&goal.id,"ai_ollama",&goal.revision,crate::assistant_memory::now()).unwrap();assert_eq!(held.grant.as_ref().unwrap().owner.state,State::Unavailable);assert!(!held.scan_complete&&!held.recovery_available);drop(absent);
    let view=store.reconciliation(&root(&fixture),&goal.id,"ai_ollama",&goal.revision,crate::assistant_memory::now()).unwrap();assert_eq!(view.grant.as_ref().unwrap().owner.state,State::OwnerAbsent);assert!(view.scan_complete);assert!(!view.execution_available&&!view.recovery_available);assert_eq!(snapshot(&profile),before);
    let main=Chat::persistent(profile.join("new-main.json"));let controller=Controller::new().unwrap();assert!(controller.prepare(&goal,&root(&fixture),&profile.join("contexts"),&main,&evidence(&goal,100_008),"cannot-take-over".into(),100_008,Arc::new(|_,_,_|Validity::Current)).is_err());assert_eq!(store.read(&goal.id,"ai_ollama").unwrap().revision,goal.revision);
    let gate=a.retained_absence(&row.spec,proof).unwrap();let(path,_)=a.owner_context().unwrap();let lock=path.join(format!("{}.lock",row.lease.as_ref().unwrap().id));std::fs::rename(&lock,lock.with_extension("original")).unwrap();std::fs::write(&lock,b"").unwrap();std::fs::set_permissions(&lock,std::os::unix::fs::PermissionsExt::from_mode(0o600)).unwrap();assert!(gate.current(&a).is_err());claim.current().unwrap();drop(gate);drop(claim);
}
